INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy8b-u1-passive-present-future', '被动语态(现在/将来)', 'A2', 8, '被动语态表示主语是动作的承受者,由 be+过去分词 构成。一般现在时被动:am/is/are+过去分词(English is spoken here. / These cars are made in China.);一般将来时被动:will be+过去分词(The work will be done soon.)。主语单数用 is、复数用 are;动作发出者用 by 引出。否定在 be/will 后加 not;一般疑问把 be/will 提到主语前。', 1, 'wy8B', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='verb' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy8b-u2-passive-past', '被动语态(过去)', 'A2', 8, '一般过去时的被动语态:was/were+过去分词,表示过去主语承受的动作。主语单数用 was、复数用 were(The window was broken yesterday. / These photos were taken last year.)。动作发出者用 by 引出;否定在 was/were 后加 not;一般疑问把 was/were 提到主语前。', 2, 'wy8B', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='verb' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy8b-u3-modals-1', '情态动词(一)', 'A2', 8, '情态动词后接动词原形。can/could 表能力(I can swim. / She could read at four);can/may 表许可(May I come in?);may/might 表可能(It may rain);must/have to 表义务(You must finish it. / We have to wear uniforms)。must 是主观必须,have to 是客观不得不;情态动词没有人称和数的变化(he can,不是 he cans)。', 3, 'wy8B', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='other' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy8b-u4-modals-2', '情态动词(二)·推测与建议', 'A2', 8, '情态动词表推测,强度不同:must 表有把握的肯定推测"一定"(He must be tired);may/might 表没把握的推测"可能"(She may be at home);can''t 表否定推测"不可能"(It can''t be true)。这些后常接 be+形容词/名词。表建议用 should/ought to"应该"(You should see a doctor)。判断时要读语境,看说话人对可能性的判断强弱。', 4, 'wy8B', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='other' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy8b-u5-object-clauses-1', '宾语从句(一)·that', 'A2', 8, '宾语从句是作动词宾语的从句。由陈述句充当时,用连词 that 引导(常可省略):I think (that) he is right. 从句用陈述语序(主语+谓语),不用疑问语序。时态呼应:主句是现在时,从句按需要选时态;主句是过去时,从句一般也用过去的某种时态(He said he was busy);但从句表示客观真理时仍用一般现在时(The teacher told us that the earth moves around the sun)。', 5, 'wy8B', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='other' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy8b-u6-object-clauses-2', '宾语从句(二)·if/whether/wh-', 'A2', 8, '由一般疑问句充当宾语从句时,用 if 或 whether 引导,意为"是否":I don''t know if/whether he will come. 由特殊疑问句充当时,用原来的疑问词(what/where/when/who/how…)引导:Could you tell me where he lives? ★宾语从句一律用陈述语序(连接词+主语+谓语),不能用疑问语序(不说 where does he live)。', 6, 'wy8B', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='other' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u1-passive-present-future'), 'English ____ in many countries.', 'is spoken', 'is speaking', 'speaks', 'speak', 'A', '主语 English 单数,一般现在时被动 is+过去分词 spoken。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u1-passive-present-future'), 'These machines ____ in that factory.', 'makes', 'are made', 'are making', 'make', 'B', '主语复数,一般现在时被动 are+过去分词 made。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u1-passive-present-future'), '改为被动语态: People clean the classroom every day. ____', 'The classroom was cleaned every day.', 'The classroom is cleaning every day.', 'The classroom cleans every day.', 'The classroom is cleaned every day.', 'D', '主动 clean the classroom→被动:宾语 classroom 作主语,一般现在时 is+过去分词 cleaned。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u1-passive-present-future'), 'Rubbish ____ into the bin.', 'is throwing', 'throw', 'is thrown', 'throws', 'C', 'is+过去分词 thrown。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u1-passive-present-future'), 'Many trees ____ every spring.', 'are planted', 'planting', 'plant', 'plants', 'A', '主语复数,are+过去分词 planted。', 1, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u1-passive-present-future'), '改为主动语态: These rooms are cleaned by the students every day. ____', 'The students cleaned these rooms every day.', 'These rooms clean the students every day.', 'The students are cleaned these rooms every day.', 'The students clean these rooms every day.', 'D', '被动还原主动(反向):by 后 the students 作主语,rooms 作宾语,现在时复数主语用原形 clean。', 3, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u1-passive-present-future'), 'A new library ____ next year.', 'builds', 'is building', 'will be built', 'will build', 'C', '一般将来时被动 will be+过去分词 built。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u1-passive-present-future'), 'The work ____ soon.', 'will finish', 'will be finished', 'is finishing', 'finishes', 'B', '将来时被动 will be+过去分词 finished。', 2, 8, 'mcq');
