INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u1-passive-present-future'), 'Paper ____ from wood.', 'is made', 'is making', 'make', 'makes', 'A', 'is made from 由…制成。', 1, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u1-passive-present-future'), '____ these books ____ by children?', 'Do; read', 'Are; read', 'Are; reading', 'Is; read', 'B', '复数主语被动疑问,Are 提前+过去分词 read。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u1-passive-present-future'), 'The rules ____ by everyone here.', 'follows', 'follow', 'following', 'are followed', 'D', '复数主语,are+过去分词 followed。', 2, 12, 'mcq');
