INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u1-passive-present-future'), 'These reports ____ by computer.', 'writing', 'writes', 'write', 'are written', 'D', '复数主语,are+过去分词 written。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u1-passive-present-future'), 'Rice ____ in the south of China.', 'grows', 'is grown', 'growing', 'grow', 'B', '单数主语,is+过去分词 grown。', 2, 15, 'mcq');
