INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u1-passive-present-future'), 'These old houses ____ any more.', 'isn''t used', 'not use', 'don''t use', 'aren''t used', 'D', '复数主语被动否定 aren''t used。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u1-passive-present-future'), '改为被动语态: People will build a new library next year. ____', 'A new library will be built next year.', 'A new library is built next year.', 'A new library will build next year.', 'A new library will be building next year.', 'A', '一般将来时主动 will build→被动 will be+过去分词 built;library 作主语。', 3, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u1-passive-present-future'), 'The homework ____ every evening, and the rooms ____ every morning.', 'checks; are cleaned', 'is checked; are cleaned', 'checks; clean', 'is checking; are cleaning', 'B', '两处被动:单数 is checked、复数 are cleaned。', 3, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u1-passive-present-future'), 'Trees ____ here, so the air ____ every day.', 'plant; makes', 'plant; is made', 'are planted; is made', 'are planting; is making', 'C', '复数 are planted、单数 is made(空气被净化,泛指现在时被动)。', 3, 20, 'mcq');
