INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u2-passive-past'), 'The letter ____ by Tom last night.', 'was written', 'writes', 'wrote', 'is written', 'A', '单数主语过去被动 was written。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u2-passive-past'), '改为被动语态: Tom broke the window yesterday. ____', 'The window is broken by Tom yesterday.', 'The window broke by Tom yesterday.', 'The window was breaking by Tom yesterday.', 'The window was broken by Tom yesterday.', 'D', '过去时主动 broke→被动 was+过去分词 broken;window 作主语,Tom 用 by 引出。', 3, 5, 'mcq');
