INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u2-passive-past'), '改为主动语态: The cakes were made by my mother yesterday. ____', 'My mother was made the cakes yesterday.', 'The cakes made my mother yesterday.', 'My mother made the cakes yesterday.', 'My mother makes the cakes yesterday.', 'C', '被动还原主动(反向):by 后 my mother 作主语,cakes 作宾语,过去时用 made。', 3, 17, 'mcq');
