INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u2-passive-past'), 'The house ____ last year, and new trees ____ around it.', 'built; planted', 'built; were planted', 'was building; were planting', 'was built; were planted', 'D', '单数 was built、复数 were planted,均过去被动。', 3, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u2-passive-past'), 'The words ____ on the board, and then they ____ by the students.', 'were writing; were reading', 'were written; were read', 'wrote; were read', 'wrote; read', 'B', '两处复数过去被动:were written、were read。', 3, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u3-modals-1'), 'I ____ swim when I was five years old.', 'could', 'must', 'can', 'should', 'A', '表过去的能力用 could。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u3-modals-1'), '____ I use your pen for a moment?', 'Should', 'Must', 'May', 'Need', 'C', '请求许可用 May I…?', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u3-modals-1'), 'You ____ finish your homework before dinner.', 'may', 'must', 'need', 'could', 'B', '表义务、必须用 must。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u3-modals-1'), 'It ____ rain this afternoon. Take an umbrella.', 'must', 'need', 'can', 'may', 'D', '表可能性用 may(可能会下雨)。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u3-modals-1'), 'We ____ wear school uniforms on Monday.', 'could', 'can', 'have to', 'may', 'C', '客观规定不得不用 have to。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u3-modals-1'), '____ you speak English? — Yes, a little.', 'Can', 'Should', 'Must', 'Need', 'A', '表能力用 Can you…?', 1, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u3-modals-1'), 'Look at the clouds. It ____ snow tonight.', 'must', 'might', 'need', 'can', 'B', '表不太确定的可能用 might。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u3-modals-1'), 'Students ____ run in the classroom.', 'don''t have to', 'may not', 'needn''t', 'mustn''t', 'D', '表禁止用 mustn''t(不许)。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u3-modals-1'), '— Must I clean it now? — No, you ____.', 'can''t', 'needn''t', 'couldn''t', 'mustn''t', 'B', '回答 Must…? 表"不必"用 needn''t。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u3-modals-1'), 'She ____ read simple books when she was six.', 'must', 'should', 'can', 'could', 'D', '过去的能力用 could。', 1, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u3-modals-1'), '____ I take a photo here? — Sorry, you can''t.', 'Should', 'Need', 'Can', 'Must', 'C', '请求许可 Can I…?', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u3-modals-1'), 'You ____ be late for the meeting. It''s important.', 'mustn''t', 'may not', 'needn''t', 'don''t have to', 'A', '表"绝不可"用 mustn''t。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u3-modals-1'), 'We ____ get up early tomorrow because of the trip.', 'could', 'have to', 'may', 'might', 'B', '因故不得不用 have to。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u3-modals-1'), 'He ____ play the piano very well.', 'need', 'should', 'can', 'must', 'C', '表能力用 can。', 1, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u3-modals-1'), 'It ____ be cold outside. Take a coat, just in case.', 'can', 'must', 'need', 'may', 'D', '表可能用 may。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u3-modals-1'), 'You ____ worry. Everything is fine now.', 'needn''t', 'couldn''t', 'mustn''t', 'can''t', 'A', '表"不必"用 needn''t。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u3-modals-1'), '____ we come in? — Yes, please.', 'Need', 'Should', 'Must', 'May', 'D', '请求许可 May we…?', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u3-modals-1'), 'When I was young, I ____ not ride a bike.', 'could', 'must', 'can', 'may', 'A', '过去能力否定 could not。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u3-modals-1'), 'It ____ rain later, so we ____ take our umbrellas.', 'can; might', 'might; have to', 'should; can', 'must; may', 'B', '表可能用 might;因此不得不带伞用 have to。', 3, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u3-modals-1'), 'She ____ swim when she was four, but now she ____ swim very fast.', 'can; could', 'must; can', 'could; can', 'may; could', 'C', '过去能力 could、现在能力 can。', 3, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u4-modals-2'), 'The light is on. Someone ____ be at home.', 'can''t', 'needn''t', 'must', 'may not', 'C', '有把握的肯定推测"一定"用 must。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u4-modals-2'), 'He worked all day. He ____ be very tired now.', 'needn''t', 'can''t', 'may not', 'must', 'D', '根据"干了一天"有把握推测"一定累"用 must。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u4-modals-2'), 'She isn''t answering the phone. She ____ be busy.', 'may', 'needn''t', 'mustn''t', 'can''t', 'A', '没把握的推测"可能"用 may。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u4-modals-2'), 'That ____ be John over there. John is in Beijing today.', 'may', 'can''t', 'should', 'must', 'B', '根据"John 在北京"推测"不可能是他"用 can''t。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u4-modals-2'), 'You look ill. You ____ see a doctor.', 'mustn''t', 'can''t', 'should', 'needn''t', 'C', '提建议"应该"用 should。', 1, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u4-modals-2'), 'The ground is wet. It ____ be raining outside.', 'can''t', 'may not', 'needn''t', 'must', 'D', '据"地湿"有把握推测"一定在下雨"用 must。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u4-modals-2'), 'Whose bag is this? It ____ be Lily''s; she has one like this.', 'needn''t', 'may', 'mustn''t', 'can''t', 'B', '不确定的推测"可能是"用 may。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u4-modals-2'), 'It ____ be true! Nobody can run that fast.', 'can''t', 'must', 'should', 'may', 'A', '表"不可能"用 can''t。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u4-modals-2'), 'You ____ eat more vegetables. They are good for you.', 'mustn''t', 'needn''t', 'should', 'can''t', 'C', '提建议用 should。', 1, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u4-modals-2'), 'The window is broken. The wind outside ____ be very strong.', 'needn''t', 'can''t', 'may not', 'must', 'D', '据"窗户破了"有把握推测"外面风一定很大"用 must(对现在的推测)。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u4-modals-2'), 'She speaks French so well. She ____ be from France.', 'might', 'can''t', 'mustn''t', 'needn''t', 'A', '没太大把握的推测用 might。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u4-modals-2'), 'He ____ be hungry; he had a big lunch just now.', 'should', 'can''t', 'may', 'must', 'B', '据"刚吃过"推测"不可能饿"用 can''t。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u4-modals-2'), 'It''s very late. You ____ go to bed now.', 'should', 'can''t', 'mustn''t', 'needn''t', 'A', '提建议"该"用 should。', 1, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u4-modals-2'), 'The classroom is so quiet. The students ____ be having a test.', 'needn''t', 'can''t', 'may not', 'must', 'D', '有把握推测"一定在考试"用 must。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u4-modals-2'), 'I''m not sure, but the answer ____ be wrong.', 'can''t', 'might', 'mustn''t', 'needn''t', 'B', '不确定推测用 might。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u4-modals-2'), 'This ____ be Tom''s coat. Tom is much taller than this.', 'must', 'should', 'can''t', 'may', 'C', '据"Tom 高得多"推测"不可能是"用 can''t。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u4-modals-2'), 'You ____ keep your promise. A promise is important.', 'mustn''t', 'can''t', 'needn''t', 'ought to', 'D', '提建议"应当"用 ought to。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u4-modals-2'), 'She looks worried. Something ____ be wrong.', 'needn''t', 'can''t', 'must', 'may not', 'C', '有把握推测"一定有问题"用 must。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u4-modals-2'), 'He ____ be at school now; it''s Sunday, so he ____ be at home.', 'may; must', 'can''t; may', 'must; can''t', 'should; can''t', 'B', '周日不可能在校用 can''t;可能在家用 may。', 3, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u4-modals-2'), 'The room is a mess. Someone ____ be here just now, but I ____ be sure who.', 'must; can''t', 'should; may', 'may; must', 'can''t; must', 'A', '一定有人来过用 must;不能确定是谁用 can''t。', 3, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u5-object-clauses-1'), 'I think ____ he is a good student.', 'which', 'if', 'that', 'what', 'C', '陈述句作宾语从句用 that 引导。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u5-object-clauses-1'), 'She said ____ she would come to the party.', 'whether', 'what', 'which', 'that', 'D', '陈述句宾从用 that。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u5-object-clauses-1'), 'Everyone knows ____ the sun rises in the east.', 'that', 'if', 'what', 'whether', 'A', '客观事实的陈述句宾从用 that。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u5-object-clauses-1'), 'He told me ____ he ____ busy that day.', 'if; was', 'that; was', 'that; is', 'what; was', 'B', '主句过去时,从句时态后移用 was。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u5-object-clauses-1'), 'Do you believe ____ she can finish it alone?', 'whose', 'which', 'what', 'that', 'D', '陈述句宾从用 that。', 1, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u5-object-clauses-1'), 'The teacher said ____ the earth ____ around the sun.', 'that; moves', 'that; is moving', 'that; moved', 'if; moves', 'A', '客观真理即使主句过去时,从句仍用一般现在时 moves。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u5-object-clauses-1'), 'I hope ____ you will have a good time.', 'if', 'that', 'what', 'whether', 'B', 'hope 后陈述句宾从用 that。', 1, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u5-object-clauses-1'), 'She didn''t know ____ the film ____ already begun.', 'what; had', 'that; has', 'that; had', 'if; had', 'C', '主句过去时,"已开始"用过去完成 had begun。', 3, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u5-object-clauses-1'), 'We all think ____ the story is very interesting.', 'whose', 'which', 'what', 'that', 'D', '陈述句宾从用 that。', 1, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u5-object-clauses-1'), 'He promised ____ he would help us with the work.', 'if', 'that', 'which', 'what', 'B', 'promise 后陈述宾从用 that。', 1, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u5-object-clauses-1'), 'My father said ____ he ____ to Beijing the next week.', 'that; will go', 'if; would go', 'that; would go', 'what; would go', 'C', '主句过去时,从句将来用过去将来 would go。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u5-object-clauses-1'), 'I''m sure ____ our team will win the game.', 'that', 'whether', 'what', 'which', 'A', 'be sure 后陈述宾从用 that。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u5-object-clauses-1'), 'She hoped ____ the weather ____ fine the next day.', 'what; would be', 'that; would be', 'that; will be', 'if; would be', 'B', '主句过去,从句将来用 would be。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u5-object-clauses-1'), 'They believe ____ hard work brings success.', 'what', 'which', 'that', 'if', 'C', '陈述真理宾从用 that。', 1, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u5-object-clauses-1'), 'The boy said ____ he ____ his homework already.', 'if; had finished', 'what; finished', 'that; has finished', 'that; had finished', 'D', '主句过去,"已完成"用过去完成 had finished。', 3, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u5-object-clauses-1'), 'I think ____ you are right about this question.', 'that', 'which', 'whether', 'what', 'A', '陈述宾从用 that。', 1, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u5-object-clauses-1'), 'Our teacher told us ____ light ____ faster than sound.', 'what; travels', 'that; travels', 'that; traveled', 'if; travels', 'B', '客观真理从句用一般现在时 travels。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u5-object-clauses-1'), 'She knew ____ her friends ____ waiting for her.', 'what; were', 'if; were', 'that; are', 'that; were', 'D', '主句过去,从句进行时后移用 were waiting。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u5-object-clauses-1'), 'He said ____ he ____ the film before, so he didn''t want to see it again.', 'that; had seen', 'if; had seen', 'that; has seen', 'what; saw', 'A', '主句过去,"以前看过"用过去完成 had seen。', 3, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u5-object-clauses-1'), 'I believe ____ everyone ____ do better if they keep trying.', 'that; could', 'if; can', 'that; can', 'what; can', 'C', '主句现在时,从句表能力用 can。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u6-object-clauses-2'), 'I don''t know ____ he will come to the party.', 'which', 'if', 'what', 'that', 'B', '一般疑问句作宾从用 if"是否"。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u6-object-clauses-2'), 'Could you tell me ____ the bank is?', 'if is', 'where is', 'that', 'where', 'D', '特殊疑问句宾从用 where+陈述语序 the bank is。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u6-object-clauses-2'), 'I wonder ____ she likes the present.', 'which', 'what', 'whether', 'that', 'C', '是否喜欢→用 whether"是否"。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u6-object-clauses-2'), 'Do you know ____ the film begins?', 'when', 'if does', 'when does', 'that', 'A', '特殊疑问宾从用 when+陈述语序 the film begins。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u6-object-clauses-2'), 'Can you tell me ____ he lives?', 'where does', 'where', 'that', 'where is', 'B', '宾从用陈述语序 where he lives,不用疑问语序。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u6-object-clauses-2'), 'I''m not sure ____ it will rain tomorrow.', 'that', 'what', 'which', 'whether', 'D', '是否下雨→whether。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u6-object-clauses-2'), 'Please tell me ____ you did last weekend.', 'that', 'if did', 'what', 'what did', 'C', '特殊疑问宾从 what+陈述语序 you did。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u6-object-clauses-2'), 'She asked me ____ I had finished my homework.', 'if', 'that', 'which', 'what', 'A', '一般疑问句作宾从(是否完成)用 if。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u6-object-clauses-2'), 'Do you know ____ the meeting will start?', 'that', 'if will', 'when', 'when will', 'C', '宾从陈述语序 when the meeting will start。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u6-object-clauses-2'), 'I want to know ____ the story is true or not.', 'what', 'if', 'that', 'whether', 'D', '…or not 只能用 whether(不用 if)。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u6-object-clauses-2'), 'Could you tell me ____ to the station?', 'how to get', 'how do I get', 'that get', 'how I get to', 'A', 'how+to do 作宾从,how to get to the station。', 3, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u6-object-clauses-2'), 'He asked me ____ I could help him.', 'that', 'if', 'which', 'what', 'B', '能否帮忙→if。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u6-object-clauses-2'), 'Do you know ____ that tall man is?', 'that', 'if is', 'who', 'who is', 'C', '特殊疑问宾从 who+陈述语序 that tall man is。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u6-object-clauses-2'), 'I wonder ____ the shop is open on Sundays.', 'whether', 'which', 'what', 'that', 'A', '是否营业→whether。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u6-object-clauses-2'), 'Please tell me ____ you will go there.', 'how will', 'that', 'if will', 'how', 'D', '宾从陈述语序 how you will go there。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u6-object-clauses-2'), 'She didn''t tell me ____ she was late for school.', 'that', 'why', 'if was', 'why was', 'B', '特殊疑问宾从 why+陈述语序 she was late。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u6-object-clauses-2'), 'I don''t know ____ I should take with me.', 'what should', 'if should', 'that', 'what', 'D', '宾从陈述语序 what I should take。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u6-object-clauses-2'), 'Do you know ____ he has lived here?', 'how long', 'if has', 'how long has', 'that', 'A', '宾从陈述语序 how long he has lived here。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u6-object-clauses-2'), 'She asked ____ I was free that evening and ____ I could go with her.', 'that; that', 'if; that', 'whether; if', 'what; if', 'C', '两处均"是否":whether/if 都可,后接陈述语序。', 3, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code='wy8b-u6-object-clauses-2'), 'Can you tell me ____ the new library is and ____ it opens?', 'where is; when does', 'where; when', 'where; when does', 'that; that', 'B', '两处特殊疑问宾从均陈述语序:where…is、when…opens。', 3, 20, 'mcq');
