-- 外研社八下 wy8B s4 语法灌库(junior_grammar_points/questions)· publisher=junior_fltrp · volume=wy8B · grade=8 · 6点/120题 · code 均 wy8b- 前缀(不撞 wy8A 的 wy8-)
-- 幂等:按(publisher,volume)先删后插。Aaron service role 跑。
BEGIN;

DELETE FROM public.junior_grammar_questions q USING public.junior_grammar_points p WHERE q.point_id=p.id AND p.publisher='junior_fltrp' AND p.volume='wy8B';
DELETE FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B';

-- 6 语法点

-- 120 题

-- 断言
DO $$
DECLARE ptn int; qn int; badp int; poll int; nocat int; uneven int;
BEGIN
  SELECT count(*) INTO ptn FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B';
  SELECT count(*) INTO qn FROM public.junior_grammar_questions q JOIN public.junior_grammar_points p ON q.point_id=p.id WHERE p.publisher='junior_fltrp' AND p.volume='wy8B';
  SELECT count(*) INTO badp FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND code NOT LIKE 'wy8b-%';
  SELECT count(*) INTO poll FROM public.junior_grammar_points WHERE volume='wy8B' AND publisher<>'junior_fltrp';
  SELECT count(*) INTO nocat FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8B' AND category_id IS NULL;
  SELECT count(*) INTO uneven FROM (SELECT p.code FROM public.junior_grammar_points p LEFT JOIN public.junior_grammar_questions q ON q.point_id=p.id WHERE p.publisher='junior_fltrp' AND p.volume='wy8B' GROUP BY p.code HAVING count(q.id)<>20) t;
  IF ptn<>6 THEN RAISE EXCEPTION 'point=% 期望6', ptn; END IF;
  IF qn<>120 THEN RAISE EXCEPTION 'question=% 期望120', qn; END IF;
  IF badp<>0 THEN RAISE EXCEPTION 'code_prefix_bad=%', badp; END IF;
  IF poll<>0 THEN RAISE EXCEPTION 'pep_polluted=%', poll; END IF;
  IF nocat<>0 THEN RAISE EXCEPTION 'category_null=%', nocat; END IF;
  IF uneven<>0 THEN RAISE EXCEPTION 'points_uneven=%', uneven; END IF;
  RAISE NOTICE 'OK: wy8B 语法 % 点 / % 题', ptn, qn;
END $$;

COMMIT;
SELECT p.unit, p.code, count(q.id) FROM public.junior_grammar_points p LEFT JOIN public.junior_grammar_questions q ON q.point_id=p.id WHERE p.publisher='junior_fltrp' AND p.volume='wy8B' GROUP BY p.unit,p.code,p.sort_order ORDER BY p.sort_order;